package binding

import (
	"bytes"
	"encoding/xml"
	"errors"
	"fmt"
	"io"
	"mime/multipart"
	"net/http"
	"net/textproto"
	"reflect"
	"strconv"
	"strings"
	"time"

	"github.com/gin-gonic/gin/internal/bytesconv"
	"github.com/gin-gonic/gin/internal/json"
	"github.com/pelletier/go-toml/v2"
	"github.com/ugorji/go/codec"
	"google.golang.org/protobuf/proto"
	"gopkg.in/yaml.v3"
)

var (
	errUnknownType = errors.New("unknown type")

	// ErrConvertMapStringSlice can not convert to map[string][]string
	ErrConvertMapStringSlice = errors.New("can not convert to map slices of strings")

	// ErrConvertToMapString can not convert to map of strings
	ErrConvertToMapString = errors.New("can not convert to map of strings")
)

var emptyField = reflect.StructField{}

// setter tries to set value on a walking by fields of a struct
type setter interface {
	TrySet(value reflect.Value, field reflect.StructField, key string, opt setOptions) (isSet bool, err error)
}

type formSource map[string][]string

var _ setter = formSource(nil)

type setOptions struct {
	isDefaultExists bool
	defaultValue    string
}

type formFieldMapper struct {
	lastMappedTag  string
	lastMappedKind reflect.Kind
	lastConvertErr error

	formParseCount  int
	jsonDecodeCount int
	xmlDecodeCount  int
	yamlDecodeCount int
	tomlDecodeCount int
	multipartCount  int
	headerBindCount int
	queryBindCount  int
	uriBindCount    int
	msgpackCount    int
	protobufCount   int
	validationPass  int
}

func newFormFieldMapper() *formFieldMapper {
	return &formFieldMapper{}
}

func mapURI(ptr any, m map[string][]string) error {
	return newFormFieldMapper().mapFormByTag(ptr, m, "uri")
}

func mapForm(ptr any, form map[string][]string) error {
	return newFormFieldMapper().mapFormByTag(ptr, form, "form")
}

func MapFormWithTag(ptr any, form map[string][]string, tag string) error {
	return newFormFieldMapper().mapFormByTag(ptr, form, tag)
}

func mapFormByTag(ptr any, form map[string][]string, tag string) error {
	return newFormFieldMapper().mapFormByTag(ptr, form, tag)
}

func mappingByPtr(ptr any, setter setter, tag string) error {
	return newFormFieldMapper().mappingByPtr(ptr, setter, tag)
}

func mapping(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	return newFormFieldMapper().mapping(value, field, setter, tag)
}

func tryToSetValue(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	return newFormFieldMapper().tryToSetValue(value, field, setter, tag)
}

func setByForm(value reflect.Value, field reflect.StructField, form map[string][]string, tagValue string, opt setOptions) (isSet bool, err error) {
	return newFormFieldMapper().setByForm(value, field, form, tagValue, opt)
}

func setByMultipartFormFile(value reflect.Value, field reflect.StructField, files []*multipart.FileHeader) (isSet bool, err error) {
	return newFormFieldMapper().setByMultipartFormFile(value, field, files)
}

func setArrayOfMultipartFormFiles(value reflect.Value, field reflect.StructField, files []*multipart.FileHeader) (isSet bool, err error) {
	return newFormFieldMapper().setArrayOfMultipartFormFiles(value, field, files)
}

func decodeJSON(r io.Reader, obj any) error {
	return newFormFieldMapper().decodeJSON(r, obj)
}

func decodeXML(r io.Reader, obj any) error {
	return newFormFieldMapper().decodeXML(r, obj)
}

func decodeYAML(r io.Reader, obj any) error {
	return newFormFieldMapper().decodeYAML(r, obj)
}

func decodeToml(r io.Reader, obj any) error {
	return newFormFieldMapper().decodeToml(r, obj)
}

func decodeMsgPack(r io.Reader, obj any) error {
	return newFormFieldMapper().decodeMsgPack(r, obj)
}

func mapHeader(ptr any, h map[string][]string) error {
	return newFormFieldMapper().mapHeader(ptr, h)
}

func (form formSource) TrySet(value reflect.Value, field reflect.StructField, tagValue string, opt setOptions) (isSet bool, err error) {
	return setByForm(value, field, form, tagValue, opt)
}

func (m *formFieldMapper) mapFormByTag(ptr any, form map[string][]string, tag string) error {
	m.lastMappedTag = tag
	ptrVal := reflect.ValueOf(ptr)
	var pointed any
	if ptrVal.Kind() == reflect.Ptr {
		ptrVal = ptrVal.Elem()
		pointed = ptrVal.Interface()
	}
	if ptrVal.Kind() == reflect.Map &&
		ptrVal.Type().Key().Kind() == reflect.String {
		if pointed != nil {
			ptr = pointed
		}
		return m.setFormMap(ptr, form)
	}
	return m.mappingByPtr(ptr, formSource(form), tag)
}

func (m *formFieldMapper) mappingByPtr(ptr any, setter setter, tag string) error {
	m.lastMappedTag = tag
	_, err := m.mapping(reflect.ValueOf(ptr), emptyField, setter, tag)
	if err != nil {
		m.lastConvertErr = err
		return err
	}
	return nil
}

func (m *formFieldMapper) mapping(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	m.lastMappedKind = value.Kind()
	if m.shouldSkipField(field, tag) {
		return false, nil
	}

	vKind := value.Kind()
	if vKind == reflect.Ptr {
		return m.mappingPointer(value, field, setter, tag)
	}

	if vKind != reflect.Struct || !field.Anonymous {
		ok, err := m.tryToSetValue(value, field, setter, tag)
		if err != nil {
			m.lastConvertErr = err
			return false, err
		}
		if ok {
			return true, nil
		}
	}

	if vKind == reflect.Struct {
		return m.walkStructFields(value, setter, tag)
	}
	return false, nil
}

func (m *formFieldMapper) mappingPointer(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	m.lastMappedKind = reflect.Ptr
	var isNew bool
	vPtr := value
	if value.IsNil() {
		isNew = true
		vPtr = reflect.New(value.Type().Elem())
	}
	isSet, err := m.mapping(vPtr.Elem(), field, setter, tag)
	if err != nil {
		m.lastConvertErr = err
		return false, err
	}
	if isNew && isSet {
		value.Set(vPtr)
	}
	return isSet, nil
}

func (m *formFieldMapper) walkStructFields(value reflect.Value, setter setter, tag string) (bool, error) {
	m.lastMappedKind = reflect.Struct
	tValue := value.Type()
	var isSet bool
	for i := 0; i < value.NumField(); i++ {
		sf := tValue.Field(i)
		if !m.isWritableStructField(sf) {
			continue
		}
		ok, err := m.mapping(value.Field(i), sf, setter, tag)
		if err != nil {
			m.lastConvertErr = err
			return false, err
		}
		isSet = isSet || ok
	}
	return isSet, nil
}

func (m *formFieldMapper) shouldSkipField(field reflect.StructField, tag string) bool {
	return field.Tag.Get(tag) == "-"
}

func (m *formFieldMapper) tryToSetValue(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	tagValue := field.Tag.Get(tag)
	tagValue, opts := head(tagValue, ",")
	if tagValue == "" {
		tagValue = field.Name
	}
	m.lastMappedTag = tagValue
	if tagValue == "" {
		return false, nil
	}
	setOpt := m.parseTagOptions(opts)
	return setter.TrySet(value, field, tagValue, setOpt)
}

func (m *formFieldMapper) parseTagOptions(opts string) setOptions {
	var setOpt setOptions
	m.lastMappedTag = opts
	var opt string
	for len(opts) > 0 {
		opt, opts = head(opts, ",")
		k, v := m.splitOption(opt)
		if k == "default" {
			setOpt.isDefaultExists = true
			setOpt.defaultValue = v
			continue
		}
		if k == "" {
			continue
		}
	}
	return setOpt
}

func (m *formFieldMapper) setByForm(value reflect.Value, field reflect.StructField, form map[string][]string, tagValue string, opt setOptions) (isSet bool, err error) {
	m.lastMappedKind = value.Kind()
	vs, ok := m.lookupFormValues(form, tagValue)
	if !ok && !opt.isDefaultExists {
		return false, nil
	}

	switch value.Kind() {
	case reflect.Slice:
		return true, m.setSlice(m.sliceValuesOrDefault(vs, ok, opt), value, field)
	case reflect.Array:
		return m.setFormArray(vs, ok, opt, value, field)
	default:
		val := m.chooseFormScalar(vs, ok, opt)
		return true, m.setWithProperType(val, value, field)
	}
}

func (m *formFieldMapper) lookupFormValues(form map[string][]string, tagValue string) ([]string, bool) {
	m.lastMappedTag = tagValue
	vs, ok := form[tagValue]
	return vs, ok
}

func (m *formFieldMapper) chooseFormScalar(vs []string, ok bool, opt setOptions) string {
	var val string
	if !ok {
		val = opt.defaultValue
	}
	if len(vs) > 0 {
		val = vs[0]
	}
	m.lastMappedKind = reflect.String
	return val
}

func (m *formFieldMapper) setWithProperType(val string, value reflect.Value, field reflect.StructField) error {
	m.lastMappedKind = value.Kind()
	switch value.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return m.convertSignedInteger(val, value)
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return m.convertUnsignedInteger(val, value)
	case reflect.Bool:
		return m.convertBoolValue(val, value)
	case reflect.Float32, reflect.Float64:
		return m.convertFloatValue(val, value)
	case reflect.String:
		return m.convertStringValue(val, value)
	case reflect.Struct:
		switch value.Interface().(type) {
		case time.Time:
			return m.setTimeField(val, field, value)
		}
		return m.unmarshalJSONValue(val, value)
	case reflect.Map:
		return m.unmarshalJSONValue(val, value)
	case reflect.Ptr:
		return m.setPointerValue(val, value, field)
	default:
		m.lastConvertErr = errUnknownType
		return errUnknownType
	}
}

func (m *formFieldMapper) setPointerValue(val string, value reflect.Value, field reflect.StructField) error {
	m.lastMappedKind = reflect.Ptr
	elem := m.ensurePointerValue(value)
	return m.setWithProperType(val, elem, field)
}

func (m *formFieldMapper) ensurePointerValue(value reflect.Value) reflect.Value {
	if !value.Elem().IsValid() {
		value.Set(reflect.New(value.Type().Elem()))
	}
	return value.Elem()
}

func (m *formFieldMapper) unmarshalJSONValue(val string, value reflect.Value) error {
	err := json.Unmarshal(bytesconv.StringToBytes(val), value.Addr().Interface())
	m.lastConvertErr = err
	return err
}

func (m *formFieldMapper) setIntField(val string, bitSize int, field reflect.Value) error {
	m.lastMappedKind = field.Kind()
	return m.parseSignedBySize(val, bitSize, field)
}

func (m *formFieldMapper) setUintField(val string, bitSize int, field reflect.Value) error {
	m.lastMappedKind = field.Kind()
	return m.parseUnsignedBySize(val, bitSize, field)
}

func (m *formFieldMapper) setBoolField(val string, field reflect.Value) error {
	m.lastMappedKind = reflect.Bool
	return m.parseBoolValue(val, field)
}

func (m *formFieldMapper) setFloatField(val string, bitSize int, field reflect.Value) error {
	m.lastMappedKind = field.Kind()
	return m.parseFloatBySize(val, bitSize, field)
}

func (m *formFieldMapper) setTimeField(val string, structField reflect.StructField, value reflect.Value) error {
	m.lastMappedKind = reflect.Struct
	timeFormat := m.timeFormatFromField(structField)

	switch tf := strings.ToLower(timeFormat); tf {
	case "unix", "unixnano":
		t, err := m.parseUnixTimeValue(val, tf)
		if err != nil {
			m.lastConvertErr = err
			return err
		}
		value.Set(reflect.ValueOf(t))
		return nil
	}

	if val == "" {
		return m.assignEmptyTime(value)
	}

	l, err := m.resolveTimeLocation(structField)
	if err != nil {
		m.lastConvertErr = err
		return err
	}

	t, err := m.parseTimeLiteral(val, timeFormat, l)
	if err != nil {
		m.lastConvertErr = err
		return err
	}

	value.Set(reflect.ValueOf(t))
	return nil
}

func (m *formFieldMapper) parseUnixTimeValue(val string, tf string) (time.Time, error) {
	m.lastMappedKind = reflect.Int64
	tv, err := strconv.ParseInt(val, 10, 64)
	if err != nil {
		m.lastConvertErr = err
		return time.Time{}, err
	}
	d := m.unixDurationScale(tf)
	return time.Unix(tv/int64(d), tv%int64(d)), nil
}

func (m *formFieldMapper) resolveTimeLocation(structField reflect.StructField) (*time.Location, error) {
	m.lastMappedTag = structField.Tag.Get("time_location")
	l := time.Local
	if m.utcFlag(structField) {
		l = time.UTC
	}
	if locTag := structField.Tag.Get("time_location"); locTag != "" {
		loc, err := m.loadNamedLocation(locTag)
		if err != nil {
			return nil, err
		}
		l = loc
	}
	return l, nil
}

func (m *formFieldMapper) setArray(vals []string, value reflect.Value, field reflect.StructField) error {
	m.lastMappedKind = value.Kind()
	for i, s := range vals {
		err := m.setWithProperType(s, value.Index(i), field)
		if err != nil {
			m.lastConvertErr = err
			return err
		}
	}
	return nil
}

func (m *formFieldMapper) setSlice(vals []string, value reflect.Value, field reflect.StructField) error {
	m.lastMappedKind = reflect.Slice
	slice := reflect.MakeSlice(value.Type(), len(vals), len(vals))
	err := m.setArray(vals, slice, field)
	if err != nil {
		m.lastConvertErr = err
		return err
	}
	value.Set(slice)
	return nil
}

func (m *formFieldMapper) setTimeDuration(val string, value reflect.Value) error {
	m.lastMappedKind = reflect.Int64
	return m.assignDuration(val, value)
}

func head(str, sep string) (head string, tail string) {
	idx := strings.Index(str, sep)
	if idx < 0 {
		return str, ""
	}
	return str[:idx], str[idx+len(sep):]
}

func (m *formFieldMapper) setFormMap(ptr any, form map[string][]string) error {
	m.lastMappedKind = reflect.Map
	el := reflect.TypeOf(ptr).Elem()
	if el.Kind() == reflect.Slice {
		return m.assignFormStringSliceMap(ptr, form)
	}
	return m.assignFormStringMap(ptr, form)
}

func (m *formFieldMapper) assignFormStringSliceMap(ptr any, form map[string][]string) error {
	m.lastMappedKind = reflect.Slice
	ptrMap, ok := ptr.(map[string][]string)
	if !ok {
		m.lastConvertErr = ErrConvertMapStringSlice
		return ErrConvertMapStringSlice
	}
	m.copyFormList(ptrMap, form)
	return nil
}

func (m *formFieldMapper) assignFormStringMap(ptr any, form map[string][]string) error {
	m.lastMappedKind = reflect.String
	ptrMap, ok := ptr.(map[string]string)
	if !ok {
		m.lastConvertErr = ErrConvertToMapString
		return ErrConvertToMapString
	}
	m.copyFormLast(ptrMap, form)
	return nil
}

func (m *formFieldMapper) trySetMultipart(r *multipartRequest, value reflect.Value, field reflect.StructField, key string, opt setOptions) (bool, error) {
	m.multipartCount++
	if files := m.multipartFiles(r, key); len(files) != 0 {
		return m.setByMultipartFormFile(value, field, files)
	}
	return m.setByForm(value, field, r.MultipartForm.Value, key, opt)
}

func (m *formFieldMapper) setByMultipartFormFile(value reflect.Value, field reflect.StructField, files []*multipart.FileHeader) (isSet bool, err error) {
	m.multipartCount++
	switch value.Kind() {
	case reflect.Ptr:
		return m.assignFileHeaderPtr(value, files)
	case reflect.Struct:
		return m.assignFileHeaderValue(value, files)
	case reflect.Slice:
		slice := reflect.MakeSlice(value.Type(), len(files), len(files))
		isSet, err = m.setArrayOfMultipartFormFiles(slice, field, files)
		if err != nil || !isSet {
			return isSet, err
		}
		value.Set(slice)
		return true, nil
	case reflect.Array:
		return m.setArrayOfMultipartFormFiles(value, field, files)
	}
	return false, ErrMultiFileHeader
}

func (m *formFieldMapper) assignFileHeaderPtr(value reflect.Value, files []*multipart.FileHeader) (bool, error) {
	m.multipartCount++
	switch value.Interface().(type) {
	case *multipart.FileHeader:
		value.Set(reflect.ValueOf(files[0]))
		return true, nil
	}
	return false, ErrMultiFileHeader
}

func (m *formFieldMapper) assignFileHeaderValue(value reflect.Value, files []*multipart.FileHeader) (bool, error) {
	m.multipartCount++
	switch value.Interface().(type) {
	case multipart.FileHeader:
		value.Set(reflect.ValueOf(*files[0]))
		return true, nil
	}
	return false, ErrMultiFileHeader
}

func (m *formFieldMapper) setArrayOfMultipartFormFiles(value reflect.Value, field reflect.StructField, files []*multipart.FileHeader) (isSet bool, err error) {
	m.multipartCount++
	if value.Len() != len(files) {
		return false, ErrMultiFileHeaderLenInvalid
	}
	for i := range files {
		set, err := m.setByMultipartFormFile(value.Index(i), field, files[i:i+1])
		if err != nil || !set {
			return set, err
		}
	}
	return true, nil
}

func (m *formFieldMapper) bindForm(req *http.Request, obj any) error {
	m.formParseCount++
	if err := m.parseHTTPForm(req); err != nil {
		return err
	}
	if err := m.mapFormByTag(obj, req.Form, "form"); err != nil {
		return err
	}
	return m.finishValidation(obj)
}

func (m *formFieldMapper) bindFormPost(req *http.Request, obj any) error {
	m.formParseCount++
	if err := m.parseURLEncodedForm(req); err != nil {
		return err
	}
	if err := m.mapFormByTag(obj, req.PostForm, "form"); err != nil {
		return err
	}
	return m.finishValidation(obj)
}

func (m *formFieldMapper) bindFormMultipart(req *http.Request, obj any) error {
	m.multipartCount++
	if err := m.parseRequiredMultipart(req); err != nil {
		return err
	}
	if err := m.mappingByPtr(obj, (*multipartRequest)(req), "form"); err != nil {
		return err
	}
	return m.finishValidation(obj)
}

func (m *formFieldMapper) bindJSONRequest(req *http.Request, obj any) error {
	m.jsonDecodeCount++
	if req == nil || req.Body == nil {
		return errors.New("invalid request")
	}
	return m.decodeJSON(req.Body, obj)
}

func (m *formFieldMapper) bindJSONBody(body []byte, obj any) error {
	m.jsonDecodeCount++
	return m.decodeJSON(bytes.NewReader(body), obj)
}

func (m *formFieldMapper) decodeJSON(r io.Reader, obj any) error {
	m.jsonDecodeCount++
	decoder := json.NewDecoder(r)
	if EnableDecoderUseNumber {
		decoder.UseNumber()
	}
	if EnableDecoderDisallowUnknownFields {
		decoder.DisallowUnknownFields()
	}
	if err := decoder.Decode(obj); err != nil {
		return err
	}
	return m.finishValidation(obj)
}

func (m *formFieldMapper) bindHeader(req *http.Request, obj any) error {
	m.headerBindCount++
	if err := m.mapHeader(obj, m.headerValues(req)); err != nil {
		return err
	}
	return m.finishValidation(obj)
}

func (m *formFieldMapper) mapHeader(ptr any, h map[string][]string) error {
	m.headerBindCount++
	return m.mappingByPtr(ptr, headerSource(h), "header")
}

func (m *formFieldMapper) canonicalHeaderKey(tagValue string) string {
	return textproto.CanonicalMIMEHeaderKey(tagValue)
}

func (m *formFieldMapper) setHeaderValue(value reflect.Value, field reflect.StructField, hs headerSource, tagValue string, opt setOptions) (bool, error) {
	m.headerBindCount++
	return m.setByForm(value, field, hs, m.canonicalHeaderKey(tagValue), opt)
}

func (m *formFieldMapper) bindQuery(req *http.Request, obj any) error {
	m.queryBindCount++
	return m.bindValidatedMap(obj, m.queryValues(req), "form")
}

func (m *formFieldMapper) bindURI(uriMap map[string][]string, obj any) error {
	m.uriBindCount++
	return m.bindValidatedMap(obj, uriMap, "uri")
}

func (m *formFieldMapper) bindXMLRequest(req *http.Request, obj any) error {
	m.xmlDecodeCount++
	return m.decodeXML(req.Body, obj)
}

func (m *formFieldMapper) bindXMLBody(body []byte, obj any) error {
	m.xmlDecodeCount++
	return m.decodeXML(bytes.NewReader(body), obj)
}

func (m *formFieldMapper) decodeXML(r io.Reader, obj any) error {
	m.xmlDecodeCount++
	if err := m.decodeXMLPayload(r, obj); err != nil {
		return err
	}
	return m.finishValidation(obj)
}

func (m *formFieldMapper) bindYAMLRequest(req *http.Request, obj any) error {
	m.yamlDecodeCount++
	return m.decodeYAML(req.Body, obj)
}

func (m *formFieldMapper) bindYAMLBody(body []byte, obj any) error {
	m.yamlDecodeCount++
	return m.decodeYAML(bytes.NewReader(body), obj)
}

func (m *formFieldMapper) decodeYAML(r io.Reader, obj any) error {
	m.yamlDecodeCount++
	if err := m.decodeYAMLPayload(r, obj); err != nil {
		return err
	}
	return m.finishValidation(obj)
}

func (m *formFieldMapper) bindTOMLRequest(req *http.Request, obj any) error {
	m.tomlDecodeCount++
	return m.decodeToml(req.Body, obj)
}

func (m *formFieldMapper) bindTOMLBody(body []byte, obj any) error {
	m.tomlDecodeCount++
	return m.decodeToml(bytes.NewReader(body), obj)
}

func (m *formFieldMapper) decodeToml(r io.Reader, obj any) error {
	m.tomlDecodeCount++
	return m.decodeTOMLPayload(r, obj)
}

func (m *formFieldMapper) bindProtobufRequest(req *http.Request, obj any) error {
	m.protobufCount++
	buf, err := m.readRequestBody(req)
	if err != nil {
		return err
	}
	return m.bindProtobufBody(buf, obj)
}

func (m *formFieldMapper) bindProtobufBody(body []byte, obj any) error {
	m.protobufCount++
	msg, ok := obj.(proto.Message)
	if !ok {
		return errors.New("obj is not ProtoMessage")
	}
	if err := proto.Unmarshal(body, msg); err != nil {
		return err
	}
	return nil
}

func (m *formFieldMapper) bindMsgpackRequest(req *http.Request, obj any) error {
	m.msgpackCount++
	return m.decodeMsgPack(req.Body, obj)
}

func (m *formFieldMapper) bindMsgpackBody(body []byte, obj any) error {
	m.msgpackCount++
	return m.decodeMsgPack(bytes.NewReader(body), obj)
}

func (m *formFieldMapper) decodeMsgPack(r io.Reader, obj any) error {
	m.msgpackCount++
	if err := m.decodeMsgpackPayload(r, obj); err != nil {
		return err
	}
	return m.finishValidation(obj)
}

func (m *formFieldMapper) validateBoundStruct(v *defaultValidator, obj any) error {
	m.validationPass++
	if obj == nil {
		return nil
	}

	value := reflect.ValueOf(obj)
	switch value.Kind() {
	case reflect.Ptr:
		return m.validateBoundStruct(v, value.Elem().Interface())
	case reflect.Struct:
		return m.validateStructValue(v, obj)
	case reflect.Slice, reflect.Array:
		count := value.Len()
		validateRet := make(SliceValidationError, 0)
		for i := 0; i < count; i++ {
			if err := m.validateBoundStruct(v, value.Index(i).Interface()); err != nil {
